 void ensurePlan()throws Exception{if(store.get("plan_default")==null){InputStream in=getAssets().open("default_plan.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);in.close();store.save("plan_default","plan",obj(out.toString("UTF-8")));}}
 JSONObject plan(){JSONObject r=store.get(activePlan);if(r==null){activePlan="plan_default";r=store.get(activePlan);}return r.optJSONObject("body");}
 JSONArray days(){return plan().optJSONArray("days");}JSONObject day(){chosen=Math.max(0,Math.min(chosen,days().length()-1));return days().optJSONObject(chosen);}
 String todayId(){return "record_"+date+"_"+activePlan+"_"+chosen;}
