 void render(boolean keep){if(store==null||isFinishing())return;rendering=true;int y=keep&&scroll!=null?scroll.getScrollY():0;timerLabel=null;root=vertical();root.setBackgroundColor(BG);root.setFitsSystemWindows(true);root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in.consumeSystemWindowInsets();});setContentView(root);LinearLayout head=row();head.setPadding(dp(20),dp(12),dp(20),dp(8));TextView brand=text("五练 /",27,INK,true);head.addView(brand,new LinearLayout.LayoutParams(0,-2,1));Button dateBtn=button(date,false,()->pickDate());head.addView(dateBtn,new LinearLayout.LayoutParams(dp(135),dp(42)));root.addView(head);status=text("",11,MUTED,false);status.setPadding(dp(22),0,dp(22),dp(9));root.addView(status);scroll=new ScrollView(this);scroll.setFillViewport(true);body=vertical();body.setPadding(dp(18),dp(10),dp(18),dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));nav=row();nav.setBackgroundColor(Color.WHITE);nav.setPadding(dp(6),dp(8),dp(6),dp(8));String[] keys={"train","plan","history","account"},titles={"◈ 训练","☷ 计划","◷ 记录","○ 我的"};for(int i=0;i<keys.length;i++){final String key=keys[i];Button b=button(titles[i],false,()->{page=key;recordId="";render(false);});if(page.equals(key))b.setBackground(bg(LIME,10));equal(nav,b);}root.addView(nav);switch(page){case "plan":showPlans();break;case "history":showHistory();break;case "account":showAccount();break;default:showTrain();}updateStatus();rendering=false;if(keep)scroll.post(()->scroll.scrollTo(0,y));}
